import { Combobox } from '@base-ui/react/combobox';
import { Check, Plus, Search } from 'lucide-react';
import { useMemo } from 'react';
import { usePortalDir, useI18n } from '../../i18n/I18nProvider';
import { cn } from '../../utils/cn';
import { workspaceSwitcherVariants } from './workspace-switcher.variants';
import { triggerLabel, WorkspaceOptionBody, WorkspaceTriggerContent, type Workspace } from './parts';
import type { WorkspaceSwitcherProps } from './WorkspaceSwitcher';

const CREATE_ID = '__create-workspace__';
const s = workspaceSwitcherVariants();

interface WorkspaceSearchProps extends WorkspaceSwitcherProps {
  current?: Workspace;
  createLabel: string;
  label: string;
}

/** Searchable variant of WorkspaceSwitcher: a combobox with the input inside its popup. */
export function WorkspaceSearch({
  className,
  workspaces,
  current,
  onSelect,
  onCreate,
  createLabel,
  label,
  searchPlaceholder: searchPlaceholderProp,
  emptyText: emptyTextProp,
}: WorkspaceSearchProps) {
  const { t } = useI18n();
  const searchPlaceholder = searchPlaceholderProp ?? t('workspace.search');
  const emptyText = emptyTextProp ?? t('workspace.empty');
  const dir = usePortalDir();
  const createEntry = useMemo<Workspace>(() => ({ id: CREATE_ID, name: createLabel }), [createLabel]);
  const items = useMemo(() => (onCreate ? [...workspaces, createEntry] : workspaces), [workspaces, onCreate, createEntry]);
  return (
    <Combobox.Root<Workspace>
      items={items}
      value={current ?? null}
      onValueChange={(next) => {
        if (!next) return;
        if (next.id === CREATE_ID) onCreate?.();
        else onSelect(next);
      }}
      itemToStringLabel={(w) => w.name}
      isItemEqualToValue={(a, b) => a.id === b.id}
      filter={(w, query) => w.id === CREATE_ID || `${w.name} ${w.meta ?? ''}`.toLowerCase().includes(query.trim().toLowerCase())}
      autoHighlight
    >
      <Combobox.Trigger aria-label={triggerLabel(current, label)} className={cn(s.trigger(), className)}>
        <WorkspaceTriggerContent workspace={current} />
      </Combobox.Trigger>
      <Combobox.Portal>
        <Combobox.Positioner dir={dir} className="z-50 outline-none" align="start" sideOffset={8}>
          <Combobox.Popup className={s.searchPopup()} aria-label={label}>
            <div className={s.searchField()}>
              <Search size={15} aria-hidden className={s.searchIcon()} />
              <Combobox.Input aria-label={searchPlaceholder.replace(/…$/, '')} placeholder={searchPlaceholder} className={s.searchInput()} />
            </div>
            <Combobox.Empty className={s.searchEmpty()}>{emptyText}</Combobox.Empty>
            <Combobox.List className={s.searchList()}>
              {(w: Workspace) =>
                w.id === CREATE_ID ? (
                  <Combobox.Item key={w.id} value={w} className={s.searchItem()}>
                    <span className={s.optionBody()}>
                      <span className={s.createIcon()}>
                        <Plus size={15} aria-hidden />
                      </span>
                      <span className={s.optionName()}>{w.name}</span>
                    </span>
                  </Combobox.Item>
                ) : (
                  <Combobox.Item key={w.id} value={w} className={s.searchItem()}>
                    <WorkspaceOptionBody workspace={w} current={w.id === current?.id} />
                    <Combobox.ItemIndicator className={s.searchIndicator()}>
                      <Check size={15} aria-hidden />
                    </Combobox.ItemIndicator>
                  </Combobox.Item>
                )
              }
            </Combobox.List>
          </Combobox.Popup>
        </Combobox.Positioner>
      </Combobox.Portal>
    </Combobox.Root>
  );
}

import { Plus } from 'lucide-react';
import type { ReactNode } from 'react';
import { cn } from '../../utils/cn';
import { Menu, MenuContent, MenuGroupLabel, MenuItem, MenuRadioGroup, MenuRadioItem, MenuSeparator, MenuTrigger } from '../menu';
import { workspaceSwitcherVariants } from './workspace-switcher.variants';
import { triggerLabel, WorkspaceOptionBody, WorkspaceTriggerContent, type Workspace } from './parts';
import { useI18n } from '../../i18n/I18nProvider';
import { WorkspaceSearch } from './WorkspaceSearch';

export type { Workspace } from './parts';

export interface WorkspaceSwitcherProps {
  className?: string;
  workspaces: Workspace[];
  currentId: string;
  /** Called with the chosen workspace. */
  onSelect: (workspace: Workspace) => void;
  /** Adds a "Create workspace" action at the end of the list. */
  onCreate?: () => void;
  createLabel?: string;
  /** Heading of the list (and the popup's accessible name). */
  label?: string;
  /** Adds a search field. Defaults to on when there are more than `searchThreshold` workspaces. */
  searchable?: boolean;
  searchThreshold?: number;
  searchPlaceholder?: string;
  emptyText?: ReactNode;
}

const s = workspaceSwitcherVariants();

/**
 * Two-line workspace picker for the topbar or sidebar header: logo, name and plan/role meta,
 * the current workspace checked, a search field when the list is long, and "Create workspace".
 * A menu for short lists; a searchable listbox (combobox) for long ones.
 */
export function WorkspaceSwitcher(props: WorkspaceSwitcherProps) {
  const {
    className,
    workspaces,
    currentId,
    onSelect,
    onCreate,
    createLabel: createLabelProp,
    label: labelProp,
    searchable,
    searchThreshold = 6,
  } = props;
  const { t } = useI18n();
  const createLabel = createLabelProp ?? t('workspace.create');
  const label = labelProp ?? t('workspace.switch');
  const current = workspaces.find((w) => w.id === currentId);
  if (searchable ?? workspaces.length > searchThreshold) {
    return <WorkspaceSearch {...props} current={current} createLabel={createLabel} label={label} />;
  }
  return (
    <Menu>
      <MenuTrigger aria-label={triggerLabel(current, label)} className={cn(s.trigger(), className)}>
        <WorkspaceTriggerContent workspace={current} />
      </MenuTrigger>
      <MenuContent className={s.popup()}>
        <MenuRadioGroup
          value={currentId}
          onValueChange={(id: string) => {
            const next = workspaces.find((w) => w.id === id);
            if (next) onSelect(next);
          }}
        >
          <MenuGroupLabel>{label}</MenuGroupLabel>
          {workspaces.map((w) => (
            <MenuRadioItem key={w.id} value={w.id} label={w.name} className={s.option()}>
              <WorkspaceOptionBody workspace={w} current={w.id === currentId} />
            </MenuRadioItem>
          ))}
        </MenuRadioGroup>
        {onCreate && (
          <>
            <MenuSeparator />
            <MenuItem icon={Plus} onClick={onCreate}>
              {createLabel}
            </MenuItem>
          </>
        )}
      </MenuContent>
    </Menu>
  );
}

export { WorkspaceSwitcher, type WorkspaceSwitcherProps, type Workspace } from './WorkspaceSwitcher';
export { workspaceSwitcherVariants, type WorkspaceSwitcherVariantProps } from './workspace-switcher.variants';
export { doc as workspaceSwitcherDoc } from './WorkspaceSwitcher.doc';

import { ChevronsUpDown } from 'lucide-react';
import { Avatar, getInitials } from '../avatar';
import { workspaceSwitcherVariants } from './workspace-switcher.variants';

export interface Workspace {
  id: string;
  name: string;
  /** Secondary line: plan, role, environment… */
  meta?: string;
  /** Logo image URL; initials show while it loads or if it fails. */
  logo?: string;
}

const s = workspaceSwitcherVariants();

/** Trigger name: the current workspace first (matches the visible text), then the action. */
export const triggerLabel = (current: Workspace | undefined, label: string) => (current ? `${current.name}, ${label}` : label);

export function WorkspaceLogo({ workspace, current }: { workspace: Workspace; current?: boolean }) {
  return (
    <Avatar
      src={workspace.logo}
      initials={getInitials(workspace.name)}
      size="sm"
      shape="rounded"
      tone={current ? 'primary' : 'accent'}
      className="size-[30px]"
    />
  );
}

export function WorkspaceOptionBody({ workspace, current }: { workspace: Workspace; current?: boolean }) {
  return (
    <span className={s.optionBody()}>
      <WorkspaceLogo workspace={workspace} current={current} />
      <span className={s.optionText()}>
        <span className={s.optionName()}>{workspace.name}</span>
        {workspace.meta && <span className={s.optionMeta()}>{workspace.meta}</span>}
      </span>
    </span>
  );
}

/** Trigger content: logo, name, meta and an up/down chevron. */
export function WorkspaceTriggerContent({ workspace }: { workspace?: Workspace }) {
  return (
    <>
      {workspace && <WorkspaceLogo workspace={workspace} current />}
      <span className={s.triggerText()}>
        <span className={s.triggerName()}>{workspace?.name ?? 'Select workspace'}</span>
        {workspace?.meta && <span className={s.triggerMeta()}>{workspace.meta}</span>}
      </span>
      <ChevronsUpDown size={14} aria-hidden className={s.triggerChevron()} />
    </>
  );
}

import { tv, type VariantProps } from '../../utils/tv';
import { listboxItem, listboxPopup } from '../select/select.variants';

